function openJournal(chunks) {
  let iterator = null;
  let acquired = false;
  let ended = false;
  let closing = null;
  let buffer = "";
  let line = 1;
  let decoder = new TextDecoder("utf-8");
  let decoderFinished = false;

  async function acquire() {
    if (!acquired) {
      acquired = true;
      iterator = chunks[Symbol.asyncIterator]();
    }
  }

  async function release() {
    if (iterator && typeof iterator.return === "function") {
      const current = iterator;
      iterator = null;
      await current.return();
    } else {
      iterator = null;
    }
  }

  function eventFromText(text, number) {
    if (text.trim() === "") return null;

    try {
      return { line: number, ok: true, value: JSON.parse(text) };
    } catch {
      return { line: number, ok: false, text };
    }
  }

  function takeEvent() {
    const index = buffer.indexOf("\n");
    if (index < 0) return null;

    let text = buffer.slice(0, index);
    buffer = buffer.slice(index + 1);

    if (text.endsWith("\r")) text = text.slice(0, -1);

    const event = eventFromText(text, line);
    line++;
    return event;
  }

  async function finishNormally() {
    if (ended) return;
    ended = true;

    if (!decoderFinished) {
      buffer += decoder.decode();
      decoderFinished = true;
    }

    if (buffer.length > 0) {
      const text = buffer;
      buffer = "";
      const event = eventFromText(text, line);
      line++;
      if (event) return event;
    }

    await release();
    return null;
  }

  async function fail(error) {
    if (!ended) {
      ended = true;
      try {
        await release();
      } catch {}
    }
    throw error;
  }

  async function next() {
    if (ended) return { done: true, value: undefined };

    await acquire();

    for (;;) {
      const event = takeEvent();
      if (event) return { done: false, value: event };

      let result;
      try {
        result = await iterator.next();
      } catch (error) {
        return fail(error);
      }

      if (result.done) {
        const finalEvent = await finishNormally();
        if (finalEvent) {
          return { done: false, value: finalEvent };
        }
        return { done: true, value: undefined };
      }

      try {
        buffer += decoder.decode(result.value, { stream: true });
      } catch (error) {
        return fail(error);
      }
    }
  }

  async function close() {
    if (ended && !closing) return;

    if (!closing) {
      ended = true;
      closing = (async () => {
        await release();
      })();
    }

    await closing;
  }

  return { next, close };
}
